<style scoped lang="scss" src="./simple-grid.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import WrapNode from "../wrap-node/wrap-node.vue";
import { SimpleGridAlign, SimpleGridAlignValues } from "./simple-grid.contants";

/**
 * This wraps a list of elements and places them in a grid, such that all items
 * are displayed at once.
 */
@Component({
  components: {
    WrapNode,
  },
})
export default class SimpleGrid extends Vue {
  @Prop({ type: Number }) columnWidth;
  @Prop({ type: Number }) rowHeight;
  @Prop({
    type: String,
    default: SimpleGridAlign.LEFT,
    validator: has(SimpleGridAlignValues),
  })
  align;

  availableWidth = 10;
  cellsPerRow = 1;
  totalRows = 1;
  totalCells = 1;
  renderComponent = true;

  get cellStyle() {
    return {
      width: `${this.columnWidth}px`,
      maxWidth: `${this.columnWidth}px`,
      height: `${this.rowHeight}px`,
    };
  }

  beforeMount() {
    window.addEventListener("resize", this.handleResize);
  }

  beforeUpdate() {
    this.handleResize();
  }

  mounted() {
    this.handleResize();
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  cellCount(row) {
    if ((row + 1) * this.cellsPerRow >= this.totalCells) {
      return this.totalCells - (this.totalRows - 1) * this.cellsPerRow;
    }

    return this.cellsPerRow;
  }

  cellSlot(row, col) {
    if (Array.isArray(this.$slots.default)) {
      return row * this.cellsPerRow + col;
    }

    return 0;
  }

  handleResize() {
    const container = this.$refs.container;
    if (!container) return;

    const box = container.getBoundingClientRect();

    let nodes = Array.isArray(this.$slots.default)
      ? this.$slots.default
      : [this.$slots.default];
    nodes = nodes.filter((n) => n.tag !== void 0);

    let toRender = nodes.length;

    this.availableWidth = box.width;
    this.cellsPerRow = Math.max(
      1,
      Math.floor(this.availableWidth / this.columnWidth)
    );

    if (this.cellsPerRow > 0) {
      this.totalRows = Math.ceil(toRender / this.cellsPerRow);
    } else {
      this.totalRows = 0;
    }

    this.totalCells = toRender;
  }
}
</script>

<template>
  <div
    :key="`${totalRows}_${cellsPerRow}`"
    ref="container"
    :class="['SimpleGrid']"
  >
    <div
      v-for="(e, i) in totalRows"
      :key="`row${i}`"
      :class="['SimpleGrid__Row', align]"
    >
      <div
        v-for="(e, k) in cellCount(i)"
        :key="`cell${i}_${k}`"
        class="SimpleGrid__Cell"
        :style="cellStyle"
      >
        <WrapNode :value="cellSlot(i, k)"><slot /></WrapNode>
      </div>
    </div>
  </div>
</template>
